USE NovaStoreDB;
GO

-- Query 05: Customer Revenue Analysis
-- Calculate total revenue generated by each customer.
-- Sort customers from highest to lowest spending.

SELECT
    c.FullName AS [Musteri Adi],
    c.City AS [Sehir],
    COUNT(o.OrderID) AS [Siparis Sayisi],
    COALESCE(SUM(o.TotalAmount), 0) AS [Toplam Ciro]
FROM dbo.Customers AS c
LEFT JOIN dbo.Orders AS o
    ON c.CustomerID = o.CustomerID
GROUP BY
    c.CustomerID,
    c.FullName,
    c.City
ORDER BY [Toplam Ciro] DESC;
